import {CATALOG,VISITORS,HOUR,createShelf,loadShelf,grow,tend,gather,swap,discover,visitorAvailable,milestones} from './shelf-model.js?v=6';
import {plantArt,creature,rootedPlantArt,POTS,frontRims,legoFlower} from './shelf-art.js?v=6';
const $=s=>document.querySelector(s),KEY='pocket-garden-shelf-v1',OLD='pocket-garden-v1';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageOK=true,selected=0,tab='pages',view='',audio,toastTimer,expanded=false;
try{const old=JSON.parse(localStorage.getItem(OLD)||'null');state=loadShelf(localStorage.getItem(KEY),Date.now(),old);}catch{state=createShelf();storageOK=false;}
const now=()=>Date.now()+state.offset;
function save(){state.revision=(state.revision||0)+1;try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}}
function refresh(){try{const raw=localStorage.getItem(KEY),next=raw&&JSON.parse(raw);if(next?.version===2&&next.revision>state.revision)state=loadShelf(next);}catch{}grow(state,now());}
function commit(){save();render();}
function say(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function chime(){if(!state.sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();[440,554,659].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.09;o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.001,t+.18);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.19);});}catch{}}
function name(p){return p.nickname||CATALOG[p.type].name;}
function moisture(p){return p.water<.2?'Thirsty':p.water<.5?'A little dry':'Comfortable';}
function remaining(p){return p.growth>=1?'Something new to gather':p.water<=0?'Resting until watered':`About ${Math.max(1,Math.ceil((1-p.growth)*(p.cycles?CATALOG[p.type].regrow:CATALOG[p.type].first)))}h to new growth`;}
function render(){
 const focus=document.activeElement?.dataset.slot;
 $('#scene').dataset.light=state.light;
 document.body.classList.toggle('reduced',!state.motion);
 $('#plants').innerHTML=state.slots.map((id,i)=>{const p=state.plants[id],pot=POTS[i];return `<button class="plant" data-slot="${i}" data-type="${p.type}" aria-label="${escape(name(p))}, ${moisture(p).toLowerCase()}, ${p.growth>=1?'ready to gather':remaining(p)}" style="left:${pot.x/1448*100}%;bottom:${100-pot.y/1086*100}%;width:${pot.width}%">${rootedPlantArt(p.type)}${p.growth>=1?'<span class="ready-spark" aria-hidden="true">✦</span>':''}<span class="plant-name">${escape(name(p))}</span></button>`;}).join('');
 const visits=Object.keys(VISITORS).filter(type=>visitorAvailable(state,type,now()));
 $('#visitors').innerHTML=visits.filter(t=>t!=='fox').map(type=>`<button class="visitor ${type}" data-visitor="${type}" aria-label="Observe ${VISITORS[type].name.toLowerCase()}" title="${VISITORS[type].name}">${creature(type)}</button>`).join('');
 $('#fox-window').innerHTML=visits.includes('fox')?`<button class="visitor fox" data-visitor="fox" aria-label="Observe the evening fox" title="A quiet neighbour">${creature('fox')}</button>`:'';
 $('#welcome').hidden=state.onboarded;
 const completed=milestones(state).filter(m=>m.done).length;
 $('#fairy-lights').innerHTML=completed>=3?'<i></i>'.repeat(7):'';
 $('#journal-dot').hidden=completed===(state.seenPages||0);
 if(focus!==undefined)$(`[data-slot="${focus}"]`)?.focus({preventScroll:true});
}
function panel(title,kicker,content,kind){view=kind;$('#panel-title').textContent=title;$('#panel-kicker').textContent=kicker;$('#panel-content').innerHTML=content;if(!$('#panel').open)$('#panel').showModal();$('#panel').scrollTop=0;}
function closePanel(){$('#panel').close();view='';}
function plantPanel(index){refresh();selected=index;const p=state.plants[state.slots[index]],c=CATALOG[p.type];panel(name(p),'A LITTLE CARE',`${plantArt(p.type,'specimen')}<p class="plant-description">${c.note}</p><div class="care-line"><span>Feeling</span><strong>${moisture(p)}</strong></div><div class="meter" aria-label="Soil moisture ${Math.round(p.water*100)} percent"><i style="width:${p.water*100}%"></i></div><div class="care-line"><span>${p.cycles?'Another little crop':'New growth'}</span><strong>${remaining(p)}</strong></div><div class="meter" aria-label="Growth ${Math.floor(p.growth*100)} percent"><i style="width:${p.growth*100}%"></i></div><div class="action-row"><button class="action" id="water-plant">A LITTLE WATER</button><button class="action secondary" id="gather-plant" ${p.growth<1?'disabled':''}>${p.growth>=1?'GATHER':'STILL GROWING'}</button></div><p class="small-note">${p.growth>=1?`${c.item} is ready for your journal. The plant stays right here and grows again.`:`This plant takes ${c.first}h for its first crop and ${c.regrow}h for another, while the soil is moist.`}</p><button class="quiet-action" id="rename-plant">Give it a name</button>`,'plant');}
function pages(){const list=milestones(state);return `<p class="small-note">${list.filter(m=>m.done).length} of ${list.length} little chapters. Take your time.</p>${list.map(m=>`<div class="milestone"><span aria-hidden="true">${m.done?'✓':'·'}</span><div><strong>${m.name}</strong><p>${m.done?'Recorded in your journal.':m.hint}</p></div></div>`).join('')}<h2 class="inline-heading">Recently on your shelf</h2>${state.events.slice(0,8).map(e=>`<p class="log-entry">${escape(e.text)}<time>${new Date(e.time-state.offset).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</time></p>`).join('')||'<p class="small-note">Your story starts with a little care.</p>'}`;}
function visitorsPage(){return `<div class="album-grid">${Object.entries(VISITORS).map(([id,c])=>`<article class="album-card ${state.discoveries[id]?'':'locked'}">${creature(id)}<strong>${state.discoveries[id]?c.name:'A visitor to discover'}</strong><p>${state.discoveries[id]?c.note:c.hint}</p></article>`).join('')}</div><p class="small-note">Visitors return after a while. Watch the window and leaves; tap them when they arrive.</p>`;}
function keepsakes(){return `<div class="album-grid">${Object.entries(CATALOG).filter(([id])=>state.collection[id]>0).map(([id,c])=>`<article class="album-card">${plantArt(id)}<strong>${c.item}</strong><p class="count">${state.collection[id]}</p></article>`).join('')||'<p class="small-note">Your first bloom or leaf impression is waiting. Tap a sparkling plant to gather it.</p>'}</div>${state.legacy?`<h2 class="inline-heading">From your first garden</h2><p class="small-note">Your original garden save is preserved. Its plants are safely kept for future arrangements.</p><div class="album-grid">${Object.entries(state.legacy.collection||{}).filter(([,n])=>n>0).map(([id,n])=>`<article class="album-card">${plantArt(id)}<strong>${escape(CATALOG[id]?.name||id)}</strong><p class="count">${Number(n)}</p></article>`).join('')}</div>`:''}`;}
function nursery(){return `<p class="small-note">The three living pots on your shelf. The orange LEGO flower in the jade vase is a permanent ornament; it does not grow or need watering. We’ll choose other plants together later.</p><div class="album-grid">${state.slots.map(id=>{const p=state.plants[id];return `<article class="album-card">${plantArt(p.type)}<strong>${escape(name(p))}</strong><p>${CATALOG[p.type].note}</p></article>`;}).join('')}</div><p class="small-note">Your earlier plants are safely kept in the nursery save for future arrangements.</p>`;}
function journal(next=tab){refresh();tab=next;const tabs={pages:'Pages',visitors:'Visitors',keepsakes:'Keepsakes',nursery:'Plants'};state.seenPages=milestones(state).filter(m=>m.done).length;save();render();panel('A little windowsill.','YOUR FIELD JOURNAL',`<nav class="tabs" aria-label="Journal sections">${Object.entries(tabs).map(([id,label])=>`<button data-tab="${id}" aria-selected="${tab===id}">${label}</button>`).join('')}</nav>${({pages,visitors:visitorsPage,keepsakes,nursery})[tab]()}`,'journal');}
function choices(index){selected=index;const current=state.plants[state.slots[index]];panel('Make this pot your own.','YOUR PLANTS',`<p class="small-note">The current plant moves safely to your nursery. If your choice is already on the shelf, the two plants exchange places.</p><div class="album-grid">${Object.entries(CATALOG).map(([id,c])=>`<button class="album-card choice" data-swap="${id}" data-current="${id===current.type}">${plantArt(id)}<strong>${c.name}</strong><p>${c.note}</p></button>`).join('')}</div>`,'choices');}
function pickPot(type){panel('Where shall it live?','YOUR PLANTS',`<p class="small-note">Choose the pot for your ${CATALOG[type].name.toLowerCase()}.</p><div class="album-grid">${state.slots.map((id,i)=>`<button class="album-card choice" data-pot="${i}" data-type="${type}">${plantArt(state.plants[id].type)}<strong>${['Woven pot · left','Woven pot · centre','Blue-and-white pot'][i]}</strong><p>Currently ${escape(name(state.plants[id]))}</p></button>`).join('')}</div>`,'pots');}
function settings(){panel('Just how you like it.','YOUR LITTLE WORLD',`<div class="setting-row"><span>Window light</span><select id="light-choice" aria-label="Window light">${['day','dusk','night'].map(x=>`<option value="${x}" ${state.light===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="setting-row"><span>Gentle sounds</span><button id="sound-choice" aria-pressed="${state.sound}">${state.sound?'On':'Off'}</button></div><div class="setting-row"><span>Little animations</span><button id="motion-choice" aria-pressed="${state.motion}">${state.motion?'On':'Off'}</button></div><div class="setting-row"><span>Scene size</span><button id="expand-choice">${expanded?'Make it small':'A closer look'}</button></div><div class="setting-row"><span>Beside your work</span><button id="window-choice">Open small window ↗</button></div><div class="setting-row"><span>Your saved garden</span><button id="export-choice">Save a copy</button></div><div class="setting-row"><span>Restore a saved copy</span><label><span class="small-note">Choose file</span><input id="import-choice" type="file" accept="application/json,.json" aria-label="Restore saved garden" style="max-width:180px;display:block;font-size:10px"></label></div><details><summary class="small-note">About this little garden</summary><p class="small-note">Plants grow between visits. They never die. Flowers and leaves are keepsakes, not a currency. Three journal chapters light the little string of lights. The orange LEGO flower is fixed decoration; only the three living pots can be tended. Your original plants and keepsakes remain available.</p><p class="small-note">Your garden saves in this browser on this device. It does not sync to other devices. A saved copy lets you move it yourself.</p><button class="quiet-action" id="skip-choice">Preview six hours passing</button></details><p class="small-note">${storageOK?'Saved on this browser.':'Browser saving is unavailable. Save a copy to keep this session.'}</p>`,'settings');}
function shower(index){const left=[23,54,72][index];$('#particles').innerHTML=Array.from({length:7},(_,i)=>`<span class="particle" style="left:${left-7+i*2}%;top:62%;animation-delay:${i*.05}s">·</span>`).join('');setTimeout(()=>$('#particles').innerHTML='',1600);}
$('#plants').addEventListener('click',e=>{const b=e.target.closest('[data-slot]');if(b)plantPanel(Number(b.dataset.slot));});
function observe(e){const b=e.target.closest('[data-visitor]');if(!b)return;refresh();const id=b.dataset.visitor,first=!state.discoveries[id];if(discover(state,id,now())){commit();chime();say(first?`${VISITORS[id].name} — a new page in your journal.`:`${VISITORS[id].name} is back for another quiet visit.`);}}
$('#visitors').addEventListener('click',observe);$('#fox-window').addEventListener('click',observe);
$('#journal-button').addEventListener('click',()=>journal());$('#menu-button').addEventListener('click',settings);$('#close-panel').addEventListener('click',closePanel);$('#panel').addEventListener('close',()=>view='');
$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('#panel-content').addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab){journal(b.dataset.tab);return;}
 if(b.dataset.swap){refresh();swap(state,selected,b.dataset.swap,now());commit();closePanel();chime();say('A new arrangement. Everyone still has a home.');return;}
 if(b.dataset.placeType){pickPot(b.dataset.placeType);return;}
 if(b.dataset.pot!==undefined){refresh();swap(state,Number(b.dataset.pot),b.dataset.type,now());commit();closePanel();say('A little change of scenery.');return;}
 switch(b.id){
 case 'water-plant':refresh();tend(state,selected,now());commit();closePanel();shower(selected);chime();say(`A little drink for ${name(state.plants[state.slots[selected]]).toLowerCase()}.`);break;
 case 'gather-plant':{refresh();const item=gather(state,selected,now());if(item){commit();closePanel();chime();say(`${item} added to your journal. New growth is on its way.`);}break;}
 case 'change-plant':choices(selected);break;
 case 'rename-plant':{const p=state.plants[state.slots[selected]];panel('A name of its own.','YOUR PLANT',`<form id="rename-form"><label for="nickname" class="small-note">What would you like to call it?</label><input class="text-input" id="nickname" name="nickname" maxlength="36" value="${escape(p.nickname||'')}" placeholder="${CATALOG[p.type].name}"><button class="action" type="submit" style="width:100%;margin-top:18px">SAVE NAME</button></form>`,'rename');$('#nickname').focus();break;}
 case 'sound-choice':state.sound=!state.sound;commit();settings();chime();break;
 case 'motion-choice':state.motion=!state.motion;commit();settings();break;
 case 'expand-choice':expanded=!expanded;$('.shelf-shell').classList.toggle('expanded',expanded);closePanel();break;
 case 'window-choice':{const u=new URL(location.href);u.searchParams.set('companion','1');const w=window.open(u,'little-windowsill','popup=yes,width=740,height=600,resizable=yes');closePanel();say(w?'Move the little window beside your work.':'Allow popups for this site to open a small window.');break;}
 case 'skip-choice':state.offset+=6*HOUR;refresh();commit();closePanel();say('Six quiet hours later. See what has grown.');break;
 case 'export-choice':{refresh();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-little-windowsill.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('A copy of your little world, to keep.');break;}
 }
});
$('#panel-content').addEventListener('submit',e=>{if(e.target.id!=='rename-form')return;e.preventDefault();refresh();state.plants[state.slots[selected]].nickname=$('#nickname').value.trim().slice(0,36);commit();plantPanel(selected);});
$('#panel-content').addEventListener('change',async e=>{
 if(e.target.id==='light-choice'){state.light=e.target.value;commit();}
 if(e.target.id==='import-choice'){try{const file=e.target.files[0];if(!file||file.size>1000000)throw Error();const raw=JSON.parse(await file.text());if(raw.version!==2||!raw.plants||!raw.slots)throw Error();const restored=loadShelf(raw,Date.now(),null,true);if(!restored)throw Error();state=restored;grow(state,now());commit();closePanel();say('Your saved windowsill is home again.');}catch{say('That file is not a valid windowsill save. Your garden is unchanged.');}}
});
$('#temple').addEventListener('click',()=>{$('#scene').classList.toggle('temple-dim');chime();say('A little adventure, quietly glowing.');});
$('#creeper').addEventListener('click',()=>{chime();say('Still only one face. A familiar little friend.');});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const s=JSON.parse(e.newValue);if(s.revision>state.revision){state=loadShelf(s);render();if(view==='plant')plantPanel(selected);}}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){refresh();commit();}});
window.addEventListener('pagehide',()=>{refresh();save();});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||$('#panel').open)return;if(e.key.toLowerCase()==='j')journal();if(e.key==='Escape'&&expanded){expanded=false;$('.shelf-shell').classList.remove('expanded');}});
$('#pot-fronts').innerHTML=frontRims();$('#lego-flower').innerHTML=legoFlower();
grow(state,now());commit();setInterval(()=>{if(!document.hidden){refresh();commit();}},30000);
